#!/usr/bin/env python3
"""Build an independent, dependency-free static cat guide. All content is escaped."""
import json,html,shutil,argparse
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
A=json.loads((ROOT/'content/articles.json').read_text())
NAME='ねこのとなり'
SITE_URL='https://hirogarushumi.com/neko-guide/'
def e(s):return html.escape(str(s),quote=True)
def icon(n):
 paths={'home':'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7','bowl':'M3 12h18a9 9 0 0 1-18 0ZM7 4v4m5-5v5m5-4v4','tray':'M3 8h18l-2 12H5L3 8ZM7 4h10','cross':'M9 3h6v6h6v6h-6v6H9v-6H3V9h6V3Z','shield':'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7l-9-4ZM8 12l3 3 5-6','heart':'M12 21S2 15 2 8a5 5 0 0 1 10-1A5 5 0 0 1 22 8c0 7-10 13-10 13Z'}
 return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{paths.get(n,paths["home"])}"/></svg>'
def card(a):return f'''<a class="article-card" href="articles/{e(a['slug'])}/" data-category="{e(a['category'])}" data-search="{e(a['title']+' '+a['description']+' '+a['category'])}"><div class="card-art art-{e(a['icon'])}">{icon(a['icon'])}<span>{e(a['category'])}</span></div><div class="card-body"><span class="category">{e(a['category'])}</span><h3>{e(a['title'])}</h3><p>{e(a['description'])}</p><span class="read-link">記事を読む <span aria-hidden="true">↗</span></span></div></a>'''
def layout(title,description,body,base='./',section='home',page_path='',indexable=True):
 canonical=SITE_URL+page_path
 robots='index,follow,max-image-preview:large' if indexable else 'noindex,nofollow'
 page_title=NAME+'｜初めての猫との暮らしガイド' if title==NAME else title+' | '+NAME
 seo=f'<link rel="canonical" href="{e(canonical)}"><meta property="og:type" content="website"><meta property="og:locale" content="ja_JP"><meta property="og:site_name" content="{NAME}"><meta property="og:title" content="{e(page_title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{e(canonical)}"><meta property="og:image" content="{SITE_URL}assets/hero-cat.webp">' if indexable else ''
 return f'''<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><base href="{base}"><meta name="robots" content="{robots}">{seo}<meta name="description" content="{e(description)}"><title>{e(page_title)}</title><link rel="icon" href="assets/mark.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/style.css"><script src="assets/site.js" defer></script></head><body><a class="skip" href="#main">本文へ</a><header class="site-header"><a class="brand" href="./"><img src="assets/mark.svg" alt="" width="42" height="42"><span>{NAME}<small>西東京から、猫との暮らしを伝える</small></span></a><button class="menu-button" type="button" aria-expanded="false" aria-controls="site-nav">メニュー <span aria-hidden="true">☰</span></button><nav id="site-nav" aria-label="メインメニュー"><a href="guides/" {'aria-current="page"' if section=='guides' else ''}>飼い方を知る</a><a href="welcome/" {'aria-current="page"' if section=='welcome' else ''}>保護猫を迎える</a><a href="local/" {'aria-current="page"' if section=='local' else ''}>西東京の地域案内</a><a class="nav-about" href="about/">このサイトについて ↗</a></nav></header><main id="main">{body}</main><footer class="site-footer"><div><a class="brand" href="./"><img src="assets/mark.svg" alt="" width="36" height="36"><span>{NAME}</span></a><p>初めて猫と暮らす人へ。<br>迎える準備から、毎日の世話まで。</p></div><nav aria-label="フッターメニュー"><a href="guides/">飼い方を知る</a><a href="welcome/">保護猫を迎える</a><a href="local/">西東京の地域案内</a><a href="about/">運営・掲載方針</a><a href="privacy/">プライバシーについて</a></nav><div class="footer-bottom"><small>西東京を拠点とする、個人運営の情報サイトです。</small><small>© {NAME}</small></div></footer></body></html>'''
def heading(k,title,text):return f'<div class="page-heading"><p class="eyebrow">{k}</p><h1>{title}</h1><p>{text}</p></div>'
def build(dest):
 dest.mkdir(parents=True,exist_ok=True);shutil.copytree(ROOT/'assets',dest/'assets',dirs_exist_ok=True)
 def put(path,title,desc,body,section='home'):
  p=dest/path/'index.html';p.parent.mkdir(parents=True,exist_ok=True);depth=len(Path(path).parts) if path else 0;p.write_text(layout(title,desc,body,'../'*depth if depth else './',section,page_path=(path+'/' if path else '')))
 home='''<section class="hero"><div class="hero-copy"><p class="eyebrow">はじめての猫との暮らし</p><h1>猫と暮らす。<br>まず、何から<br>始めよう。</h1><p>ごはんのこと、トイレのこと、病院のこと。<br>初めてだと迷うことを、一つずつ。<br>保護猫を迎える前の準備も、ここから。</p><a class="button primary" href="guides/">飼い方の基本を読む <span aria-hidden="true">→</span></a><a class="text-link" href="welcome/">これから猫を迎えたい方へ ↗</a></div><div class="hero-image"><img src="assets/hero-cat.webp" width="1536" height="1024" alt="窓辺のクッションに座る茶白の猫を描いたイラスト" fetchpriority="high"><span class="image-note">イメージイラスト</span></div><div class="hero-label"><span aria-hidden="true">✳</span> 猫を迎える前も、迎えてからも。</div></section>
<section class="start-section section"><div class="section-heading"><div><p class="eyebrow">WHERE TO START</p><h2>今、気になっていることは？</h2></div><p>近いものから、読んでみてください。</p></div><div class="topic-grid"><a href="guides/?category=迎える準備"><span class="topic-number">01</span><h3>猫を迎える準備</h3><p>最初の数日の過ごし方と、<br>安心して過ごせる部屋づくり。</p><span class="arrow" aria-hidden="true">↗</span></a><a href="guides/?category=毎日の世話"><span class="topic-number">02</span><h3>毎日のごはんとトイレ</h3><p>何を選んで、どう世話する？<br>まず知っておきたい基本から。</p><span class="arrow" aria-hidden="true">↗</span></a><a href="articles/vet-visit/"><span class="topic-number">03</span><h3>体調が気になるとき</h3><p>普段との違いの記録と、<br>動物病院への相談のしかた。</p><span class="arrow" aria-hidden="true">↗</span></a></div></section>'''
 home+='<section class="section guides-section"><div class="section-heading"><div><p class="eyebrow">CAT CARE GUIDE</p><h2>はじめに読んでおきたい記事</h2></div><a class="text-link" href="guides/">すべての記事を見る ↗</a></div><div class="article-grid">'+''.join(card(x) for x in A[:3])+'</div></section>'
 home+='''<section class="adopt-banner section"><div class="adopt-icon">'''+icon('heart')+'''</div><div><p class="eyebrow">ADOPT, DON'T SHOP</p><h2>保護猫を迎える、という選択。</h2><p>出会う前に、知っておきたいことがあります。<br>譲渡までの流れや、地域の相談先を紹介します。</p><a class="button primary" href="welcome/">保護猫を迎える前に <span aria-hidden="true">→</span></a></div><div class="banner-aside"><span>西東京から</span><strong>猫との暮らしを<br>考える人へ。</strong><a href="local/">地域の案内を見る ↗</a></div></section><section class="section about-strip"><p class="eyebrow">ABOUT</p><h2>猫を初めて飼うときの、<br>「どうしたらいい？」を減らしたい。</h2><div><p>西東京を拠点に、猫の飼い方や保護猫を迎える準備について発信する個人サイトです。運営者自身も、保護猫と暮らしています。</p><p>現在、猫の保護・譲渡や引き取りは行っていません。</p><a class="text-link" href="about/">運営者と、このサイトについて ↗</a></div></section>'''
 put('',NAME,'初めて猫を飼う人へ。猫を迎える準備、ごはんやトイレの世話、動物病院への相談、保護猫の迎え方を紹介します。',home)
 guides=heading('CAT CARE GUIDE','猫の飼い方を知る','迎える前の準備から毎日の世話まで、気になることから探せます。')+'''<section class="section library"><form class="guide-search" role="search"><label for="guide-query">記事を探す</label><div><input id="guide-query" name="q" type="search" placeholder="ごはん、トイレ、動物病院など" maxlength="100"><button class="button primary" type="submit">検索</button></div></form><div class="filter-list" role="group" aria-label="記事のカテゴリー">'''+''.join(f'<button type="button" data-filter="{e(c)}" aria-pressed="{str(c=="すべて").lower()}">{e(c)}</button>' for c in ['すべて','迎える準備','毎日の世話','健康のこと','保護猫を迎える'])+'''</div><p id="search-count" role="status" aria-live="polite"></p><div class="article-grid">'''+''.join(card(x) for x in A)+'''</div><p class="empty" hidden>該当する記事はありません。別の言葉やカテゴリーで探してみてください。</p><noscript><p>検索と絞り込みにはJavaScriptが必要です。記事は下の一覧から読めます。</p></noscript></section>'''
 put('guides','猫の飼い方を知る','猫を迎える準備、食事、トイレ、健康、保護猫の迎え方についての記事一覧。',guides,'guides')
 for a in A:
  body=f'<div class="article-wrap"><nav class="crumb" aria-label="パンくず"><a href="./">ホーム</a><span>/</span><a href="guides/">飼い方を知る</a></nav><header class="article-heading"><span class="category">{e(a["category"])}</span><h1>{e(a["title"])}</h1><p>{e(a["description"])}</p><span class="article-meta">個人運営の飼育ガイド</span></header>'
  if a.get('medical'):body+='<aside class="medical-note"><strong>緊急時は、動物病院へ直接連絡してください。</strong><p>この記事は一般的な情報です。獣医師による診察や個別の診断に代わるものではなく、獣医師の監修は受けていません。</p></aside>'
  body+='<div class="article-layout"><article class="article-body">'
  for i,s in enumerate(a['sections']):
   body+=f'<section id="section-{i}"><h2>{e(s["heading"])}</h2>'+''.join('<p>'+e(t)+'</p>' for t in s['paragraphs'])+'</section>'
  body+='</article><aside class="toc"><p>この記事の内容</p><ol>'+''.join(f'<li><a href="articles/{a["slug"]}/#section-{i}">{e(s["heading"])}</a></li>' for i,s in enumerate(a['sections']))+'</ol></aside></div><aside class="article-bottom"><strong>猫によって、合う方法は違います。</strong><p>体調に関する判断は、かかりつけの動物病院へ相談してください。この記事で扱う情報の確認先は、<a href="about/#sources">掲載方針</a>にまとめています。</p></aside><a class="text-link" href="guides/">← 記事一覧へ戻る</a></div>'
  put('articles/'+a['slug'],a['title'],a['description'],body,'guides')
 welcome=heading('WELCOME A RESCUE CAT','保護猫を迎えたいと思ったら。','出会いを探す前に、これから一緒に暮らせるかを考えるところから。')+'''<section class="section welcome-grid"><div class="reading"><h2>迎えるまでの、おおまかな流れ</h2><ol class="steps"><li><span>01</span><div><h3>住まいと家族の気持ちを確認する</h3><p>飼育できる住まいか、家族全員が賛成しているか。費用や留守中の世話も話しておきます。</p></div></li><li><span>02</span><div><h3>譲渡元へ相談する</h3><p>行政の譲渡案内や、保護団体の公式情報を探します。猫の性格や、自分の暮らしに合うかを相談しましょう。</p></div></li><li><span>03</span><div><h3>面談・トライアルへ進む</h3><p>手順や条件は譲渡元によって違います。費用、通院歴、トライアル中の相談先も確認してください。</p></div></li><li><span>04</span><div><h3>迎えてからも、困ったら相談する</h3><p>食事や猫砂など、以前の暮らしについて教えてもらいます。体調の変化は動物病院へ相談してください。</p></div></li></ol><a class="text-link" href="articles/adoption-steps/">譲渡会へ行く前に知っておきたいこと ↗</a></div><aside class="check-panel"><p class="eyebrow">BEFORE YOU WELCOME</p><h2>迎える前の確認メモ</h2><p>準備できた項目にチェックを入れられます。</p><div class="checklist">'''+''.join(f'<label><input type="checkbox" data-check="{i}"><span>{t}</span></label>' for i,t in enumerate(['住まいで猫の飼育が認められている','家族全員で話し合った','日々の世話と費用を考えた','窓や玄関の脱走対策をした','食器・トイレ・キャリーを用意した','通える動物病院を調べた']))+'''</div><p class="check-progress" role="status" aria-live="polite">0 / 6 項目を確認</p><p class="save-note">チェックは、このブラウザに保存されます。</p><button class="reset-checks text-link" type="button">チェックをすべて外す</button><p class="storage-error" role="alert" hidden>このブラウザには保存できません。チェックは画面を閉じると失われます。</p></aside></section><section class="section local-cta"><h2>西東京周辺で、相談先を探す</h2><p>まずは行政が案内する譲渡情報や、動物愛護の窓口を確認してみてください。</p><a class="button primary" href="local/">地域の案内を見る →</a></section>'''
 put('welcome','保護猫を迎える','保護猫を迎えるまでの流れと、準備のチェックリスト。',welcome,'welcome')
 local=heading('NISHITOKYO','西東京の地域案内','保護猫の譲渡や飼育について調べたいときの、情報の探し方をまとめています。')+'''<section class="section reading local-reading"><h2>まずは、行政の公式案内から</h2><p>譲渡の案内や動物に関する相談先は、自治体の公式サイトでも調べられます。下のリンクから公式サイトを開き、サイト内で「猫」「譲渡」「動物愛護」などの言葉を検索してください。</p><div class="resource-list"><a href="https://www.city.nishitokyo.lg.jp/" target="_blank" rel="noopener noreferrer"><strong>西東京市 公式サイト</strong><span>市内の動物に関する案内や相談窓口を探す</span><small>公式サイトを開く ↗（別タブ）</small></a><a href="https://www.hokeniryo.metro.tokyo.lg.jp/" target="_blank" rel="noopener noreferrer"><strong>東京都保健医療局 公式サイト</strong><span>動物愛護相談センターや、譲渡に関する情報を探す</span><small>公式サイトを開く ↗（別タブ）</small></a></div><h2>譲渡会は、最新の開催案内を確認する</h2><p>日付、場所、予約の要否、主催者を確認します。過去の開催記事や検索結果だけで判断せず、主催者の最新の案内を見てから出かけてください。</p><p>このサイトでは、現在開催中と確認できていない譲渡会を、開催予定として紹介しません。団体との提携や、譲渡の仲介も行っていません。</p><h2>猫の引き取りや、緊急の保護について</h2><p>当サイトでは、猫の引き取りや保護の依頼は受け付けていません。飼育や動物に関する相談先は、自治体の公式案内で確認してください。負傷した猫など、急を要する場合も、まず対応できる窓口へ直接連絡してください。</p></section>'''
 put('local','西東京の地域案内','西東京で保護猫の譲渡や飼育の相談先を探すための案内。',local,'local')
 about=heading('ABOUT THIS SITE','猫との暮らしを、これから始める人へ。','西東京を拠点に、猫の飼い方と保護猫の迎え方について発信します。')+'''<section class="section reading"><h2>運営者について</h2><p>現在、保護猫のまんもすと暮らしています。これまで8匹の猫と暮らしてきました。</p><p>猫を初めて飼うとき、食事やトイレ、病院のことなど、迷う場面はたくさんあります。そうしたときに、何を確かめればよいかが分かるサイトを作りたいと思い、発信を始めました。</p><h2>このサイトで行うこと</h2><p>猫を迎える準備や日々の世話についての記事と、保護猫を迎えたい人に向けた情報を掲載します。現在、保護・譲渡活動や、猫の引き取り、寄付の募集は行っていません。</p><h2 id="sources">記事の掲載方針</h2><p>運営者自身の経験と、一般的な飼育情報は分けて扱います。獣医師の監修を受けたサイトではありません。健康に関する記事は診断や治療を目的とせず、受診や相談のための基本情報として掲載します。</p><p>自治体や団体の情報は、公式発表を確認してから紹介します。日時や参加条件を確認できない譲渡会を、開催予定として掲載することはありません。</p><p>資料の整理や文章の下書き、イラストの制作にはAIを使用します。実際に経験していない出来事を体験談として掲載せず、架空のイラストを譲渡対象の猫の写真として使いません。</p><h2>公式情報を調べるときに</h2><p>動物愛護や飼育に関する公的な情報は、<a href="https://www.env.go.jp/" target="_blank" rel="noopener noreferrer">環境省の公式サイト</a>でも探せます。個別の猫の体調については、動物病院へ相談してください。</p></section>'''
 put('about','運営・掲載方針','運営者と情報の掲載方針について。保護猫と暮らす個人が西東京を拠点に発信します。',about)
 privacy=heading('PRIVACY','プライバシーについて','このサイトで扱う情報と、ブラウザへの保存について。')+'''<section class="section reading"><h2>チェックリストの保存</h2><p>「保護猫を迎える」ページのチェック内容は、使用しているブラウザ内に保存されます。名前や住所は入力せず、チェック内容を運営者へ送信することもありません。「チェックをすべて外す」ボタンや、ブラウザのサイトデータ削除で消去できます。</p><h2>アクセスに関する情報</h2><p>この専用サイトには、独自のアクセス解析ツールや広告を設置していません。ただし、配信に使用するサーバーでは、通常のアクセスログが記録される場合があります。</p><h2>外部サイトへのリンク</h2><p>外部リンクを開くと、移動先のサイトが定める方針に従って情報が取り扱われます。外部サイトの掲載内容や対応については、各運営者へご確認ください。</p><h2>今後の変更</h2><p>広告や問い合わせフォームなどを追加する場合は、必要な説明をこのページへ追記します。</p></section>'''
 put('privacy','プライバシーについて','ブラウザに保存する情報と、外部リンクについて。',privacy)
 (dest/'404.html').write_text(layout('ページが見つかりません','指定されたページはありません。',heading('NOT FOUND','ページが見つかりませんでした。','リンクが変わったか、ページが削除された可能性があります。')+'<div class="section"><a class="button primary" href="./">ホームへ戻る →</a></div>','/neko-guide/',indexable=False))
 routes=['','guides/','welcome/','local/','about/','privacy/']+['articles/'+a['slug']+'/' for a in A]
 sitemap='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+e(SITE_URL+r)+'</loc></url>' for r in routes)+'</urlset>\n'
 (dest/'sitemap.xml').write_text(sitemap)
 print(f'Built {len(list(dest.rglob("*.html")))} pages in {dest}')
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--output',type=Path,default=ROOT/'build');args=p.parse_args();build(args.output)
